def _isqrt(n):
    """Exact integer floor square root of a non-negative int, via Newton's method."""
    if n < 0:
        raise ValueError("negative input")
    if n < 2:
        return n
    # Initial estimate.
    x = 1 << ((n.bit_length() + 1) // 2)
    while True:
        y = (x + n // x) // 2
        if y >= x:
            break
        x = y
    # Newton's method can overshoot by one for exact squares; correct it.
    while x * x > n:
        x -= 1
    while (x + 1) * (x + 1) <= n:
        x += 1
    return x


def sqrt_int(n):
    """Return the exact integer square root of n.

    For a perfect square n, this is the (unique) integer whose square equals
    n. For a non-perfect square there is no integer whose square equals n, so
    an "exact" root cannot exist; in that case the floor root is returned and
    it can be verified via (sqrt_int(n) ** 2 <= n < (sqrt_int(n) + 1) ** 2).
    """
    return _isqrt(n)
